using System.Text.Json;
using System.Text.Json.Nodes;
using ForgeCore.Core;
namespace ForgeCore.Core.Tests;
public sealed class ConnectedInteriorEvidenceTests
{
    private static JsonObject Detail()=>JsonSerializer.SerializeToNode(new{schemaVersion=1,profile=ConnectedInteriorEvidence.Id,source="original_code_authored_geometry_and_screen_pattern",screenWidth=256,screenHeight=128,partsBeforeMaterialBatch=105,addedTriangles=4620,addedColliders=0,additionalMaterialBatches=1,screenTextureBytes=102639,collisionUnchanged=true,visualReviewed=false,rightsReviewed=false,stageComplete=false,animationsChanged=false,audioChanged=false})!.AsObject();
    private static JsonObject Comparison()=>JsonSerializer.SerializeToNode(new{schemaVersion=1,profile=ConnectedInteriorEvidence.Id,scope=ConnectedInteriorEvidence.ComparisonScope,baseline=ConnectedInteriorEvidence.Baseline,width=1536,height=1296,viewCount=3,magentaPixels=0,changedPixels=529521,protectedPoseTransforms=99,combatAndObjectivePosesUnchanged=true,humanArtAccepted=false,stageComplete=false,views=new[]{"warehouse_entry","warehouse_reverse","control_room_workstations"}})!.AsObject();
    [Fact]public void ValidDetailAndSamePoseStaticComparisonAreTechnicalOnly(){using var a=JsonDocument.Parse(Detail().ToJsonString());using var b=JsonDocument.Parse(Comparison().ToJsonString());ConnectedInteriorEvidence.ValidateDetail(a.RootElement);ConnectedInteriorEvidence.ValidateComparison(b.RootElement);}
    [Theory][InlineData("schemaVersion","2")][InlineData("profile","\"other\"")][InlineData("source","\"downloaded_unknown\"")][InlineData("screenWidth","512")][InlineData("screenHeight","256")][InlineData("partsBeforeMaterialBatch","181")][InlineData("addedTriangles","20001")][InlineData("addedColliders","1")][InlineData("additionalMaterialBatches","2")][InlineData("screenTextureBytes","0")][InlineData("screenTextureBytes","131073")][InlineData("collisionUnchanged","false")][InlineData("visualReviewed","true")][InlineData("rightsReviewed","true")][InlineData("stageComplete","true")][InlineData("animationsChanged","true")][InlineData("audioChanged","true")][InlineData("audioChanged","\"false\"")]
    public void DetailBoundsAndFalseApprovalClaimsFailClosed(string key,string value){var r=Detail();r[key]=JsonNode.Parse(value);using var d=JsonDocument.Parse(r.ToJsonString());Assert.Throws<InvalidDataException>(()=>ConnectedInteriorEvidence.ValidateDetail(d.RootElement));}
    [Theory][InlineData("schemaVersion","2")][InlineData("profile","\"other\"")][InlineData("scope","\"runtime_gameplay\"")][InlineData("baseline","\"previous_binary\"")][InlineData("width","2048")][InlineData("height","1024")][InlineData("viewCount","2")][InlineData("magentaPixels","1")][InlineData("changedPixels","999")][InlineData("changedPixels","995329")][InlineData("protectedPoseTransforms","9")][InlineData("protectedPoseTransforms","1025")][InlineData("combatAndObjectivePosesUnchanged","false")][InlineData("humanArtAccepted","true")][InlineData("stageComplete","true")][InlineData("humanArtAccepted","\"false\"")][InlineData("views","[\"wrong\"]")]
    public void StaticComparisonCannotBecomeRuntimeOrHumanAcceptance(string key,string value){var r=Comparison();r[key]=JsonNode.Parse(value);using var d=JsonDocument.Parse(r.ToJsonString());Assert.Throws<InvalidDataException>(()=>ConnectedInteriorEvidence.ValidateComparison(d.RootElement));}
    [Theory][InlineData(false)][InlineData(true)]
    public void MissingRequiredEvidenceCannotSilentlyUseDefaults(bool comparison){var r=comparison?Comparison():Detail();r.Remove("profile");using var d=JsonDocument.Parse(r.ToJsonString());Assert.Throws<InvalidDataException>(()=>{if(comparison)ConnectedInteriorEvidence.ValidateComparison(d.RootElement);else ConnectedInteriorEvidence.ValidateDetail(d.RootElement);});}
}
